(2837912, 395889, 41521, '<td valign="top">Excellent!</td>', 'Excellent!', '2006-09-15 11:25:15.000000', NULL, 1),
(2837949, 395889, 57202, '<td valign="top">What an awesome way to start my Friday off at work! :)  This image seriosuly made me laugh out loud.  Great job! :D  10</td>', 'What an awesome way to start my Friday off at work! :)  This image seriosuly made me laugh out loud.  Great job! :D  10', '2006-09-15 11:40:16.000000', NULL, 1),
(2837955, 394072, 57202, '<td valign="top">LOL!  This image is awesome. :)  Excellent use of DOF to blur out the people walking by in the background!  The only slight improvement I can see would have been to just SLIGHTLY rotate the image counter-clockwise to level out the top edge of the whiteboard. ;)  9</td>', 'LOL!  This image is awesome. :)  Excellent use of DOF to blur out the people walking by in the background!  The only slight improvement I can see would have been to just SLIGHTLY rotate the image counter-clockwise to level out the top edge of the whiteboard. ;)  9', '2006-09-15 11:43:39.000000', NULL, 1),
(2837963, 395804, 57202, '<td valign="top">Awesome use of selective desaturation!  Well done! :D</td>', 'Awesome use of selective desaturation!  Well done! :D', '2006-09-15 11:46:32.000000', NULL, 1),
(2837971, 394201, 57202, '<td valign="top">That''s classic!  I love that you went with a square crop.  I got a great laugh at work from this one. :)</td>', 'That''s classic!  I love that you went with a square crop.  I got a great laugh at work from this one. :)', '2006-09-15 11:48:33.000000', NULL, 1),
