(2847408, 396053, 50695, '<td valign="top">I like that you use a photographic technique to aid your joke, and that it seems original (if there is a similar cartoon it must have been executed differently). 9</td>', 'I like that you use a photographic technique to aid your joke, and that it seems original (if there is a similar cartoon it must have been executed differently). 9', '2006-09-19 12:17:13.000000', NULL, 1),
(2847409, 394635, 50695, '<td valign="top">Instead of making a cartoon, you parody Gary Larson''s drawing style. Very creative interpretation of challenge. 9</td>', 'Instead of making a cartoon, you parody Gary Larson''s drawing style. Very creative interpretation of challenge. 9', '2006-09-19 12:17:49.000000', NULL, 1),
